import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CZqXuAiL.js";const p=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about Firewall-Plus for Pterodactyl — panel vs node responsibilities, SMART detection, applies, and common gotchas.","frontmatter":{"title":"FAQ","description":"Frequently asked questions about Firewall-Plus for Pterodactyl — panel vs node responsibilities, SMART detection, applies, and common gotchas."},"headers":[],"relativePath":"firewall-plus/fwp-aside/getting-started/faq.md","filePath":"firewall-plus/fwp-aside/getting-started/faq.md","lastUpdated":1785959583000}'),i={name:"firewall-plus/fwp-aside/getting-started/faq.md"};function r(s,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-s-the-difference-between-the-panel-extension-and-the-node-service" tabindex="-1">What&#39;s the difference between the panel extension and the node service? <a class="header-anchor" href="#what-s-the-difference-between-the-panel-extension-and-the-node-service" aria-label="Permalink to &quot;What&#39;s the difference between the panel extension and the node service?&quot;">​</a></h3><p>The <strong>panel extension</strong> (Blueprint addon or standalone) owns all state: rules, lists, presets, grants, audit logs, SMART events, and the UI. The <strong>node service</strong> is a small Fastify daemon on each Wings host (default port <code>8472</code>) that receives apply payloads and turns them into atomic iptables/ipset changes, runs drift verification, and executes the SMART detection loop. They are versioned and upgraded independently — reinstalling the panel extension never touches your nodes.</p><h3 id="blueprint-or-standalone-—-which-should-i-use" tabindex="-1">Blueprint or standalone — which should I use? <a class="header-anchor" href="#blueprint-or-standalone-—-which-should-i-use" aria-label="Permalink to &quot;Blueprint or standalone — which should I use?&quot;">​</a></h3><p>Blueprint if you already run (or can run) the Blueprint framework — installs, updates, and removals are one command. Standalone if you want zero framework dependencies; the <code>install.sh</code>/<code>uninstall.sh</code> scripts merge the same files manually. Feature set is identical. See the <a href="./../index#blueprint-vs-standalone">comparison table</a>.</p><h3 id="does-firewall-plus-touch-rules-it-didn-t-create" tabindex="-1">Does Firewall-Plus touch rules it didn&#39;t create? <a class="header-anchor" href="#does-firewall-plus-touch-rules-it-didn-t-create" aria-label="Permalink to &quot;Does Firewall-Plus touch rules it didn&#39;t create?&quot;">​</a></h3><p>No. It manages only its own chains (<code>FWP-*</code>) and ipsets (<code>fwp-*</code>), and every rule it inserts is comment-tagged for idempotency. Unmanaged rules are never modified or deleted.</p><h3 id="what-firewall-backends-are-supported" tabindex="-1">What firewall backends are supported? <a class="header-anchor" href="#what-firewall-backends-are-supported" aria-label="Permalink to &quot;What firewall backends are supported?&quot;">​</a></h3><p>iptables and ipset. On modern Debian/Ubuntu hosts the daemon auto-detects and prefers the nft-backed binaries (<code>iptables-nft</code>, <code>iptables-nft-restore</code>). You can force binaries with <code>FWP_IPTABLES_BIN</code> and friends — see the <a href="./../configuration/reference#node-environment-variables">Configuration Reference</a>.</p><h2 id="rules-applies" tabindex="-1">Rules &amp; Applies <a class="header-anchor" href="#rules-applies" aria-label="Permalink to &quot;Rules &amp; Applies&quot;">​</a></h2><h3 id="i-clicked-apply-and-nothing-happened" tabindex="-1">I clicked Apply and nothing happened. <a class="header-anchor" href="#i-clicked-apply-and-nothing-happened" aria-label="Permalink to &quot;I clicked Apply and nothing happened.&quot;">​</a></h3><p>The apply is a queued job. Check, in order: (1) the queue worker is running (<code>systemctl status pteroq</code> or <code>php artisan queue:work</code>), (2) the node is ONLINE in Admin → Firewall → Nodes, (3) <code>storage/logs/laravel.log</code> for the real exception if the UI shows a generic error, (4) <code>journalctl -u firewall-plus</code> on the node.</p><h3 id="why-is-connection-timeout-missing-from-the-rule-picker" tabindex="-1">Why is <code>connection_timeout</code> missing from the rule picker? <a class="header-anchor" href="#why-is-connection-timeout-missing-from-the-rule-picker" aria-label="Permalink to &quot;Why is `connection_timeout` missing from the rule picker?&quot;">​</a></h3><p>It&#39;s a legacy type: the API still accepts it for old rows, but the node intentionally emits no rules for it, and the panel UI no longer offers it. Existing rows are harmless no-ops.</p><h3 id="why-does-geo-filter-fail-or-get-rejected" tabindex="-1">Why does <code>geo_filter</code> fail or get rejected? <a class="header-anchor" href="#why-does-geo-filter-fail-or-get-rejected" aria-label="Permalink to &quot;Why does `geo_filter` fail or get rejected?&quot;">​</a></h3><p><code>geo_filter</code> requires a MaxMind GeoLite2 database (<code>.mmdb</code>) on the node. Set <code>geoipDbPath</code> in <code>/etc/firewall-plus/config.json</code> and place the file there yourself — GeoLite2 is licensed and is <strong>not</strong> redistributed with Firewall-Plus. Enabling a geo rule without a DB is rejected rather than silently ignored. Admin → Nodes shows GeoIP availability from the last health check.</p><h3 id="how-do-whitelist-blacklist-changes-get-to-the-node" tabindex="-1">How do whitelist/blacklist changes get to the node? <a class="header-anchor" href="#how-do-whitelist-blacklist-changes-get-to-the-node" aria-label="Permalink to &quot;How do whitelist/blacklist changes get to the node?&quot;">​</a></h3><p>List mutations automatically queue an apply job; the node syncs the <code>fwp-wl-&lt;server&gt;</code> / <code>fwp-bl-&lt;server&gt;</code> ipsets as part of the same atomic apply.</p><h2 id="smart-detection" tabindex="-1">SMART Detection <a class="header-anchor" href="#smart-detection" aria-label="Permalink to &quot;SMART Detection&quot;">​</a></h2><h3 id="smart-tab-is-visible-but-the-toggle-won-t-stay-on" tabindex="-1">SMART tab is visible but the toggle won&#39;t stay on. <a class="header-anchor" href="#smart-tab-is-visible-but-the-toggle-won-t-stay-on" aria-label="Permalink to &quot;SMART tab is visible but the toggle won&#39;t stay on.&quot;">​</a></h3><p>SMART requires an admin grant. Admin → <strong>Firewall → Servers</strong> → grant SMART mode for that server, then the owner can enable it in the SMART tab and re-apply.</p><h3 id="who-gets-notified-on-an-attack-and-how" tabindex="-1">Who gets notified on an attack, and how? <a class="header-anchor" href="#who-gets-notified-on-an-attack-and-how" aria-label="Permalink to &quot;Who gets notified on an attack, and how?&quot;">​</a></h3><p>The server owner gets a <strong>Discord webhook</strong> message (if they configured one in the SMART tab) and an <strong>email alert</strong> (if the admin enabled <code>smart_owner_email_enabled</code> in settings). The admin Discord webhook (settings → <code>webhook_url</code>) receives events too. Events also land in the attack event log and can be acknowledged from the client UI or the admin Activity page; the admin Servers index shows an &quot;under mitigation&quot; badge while a mitigation is active.</p><h3 id="can-i-clear-a-mitigation-manually" tabindex="-1">Can I clear a mitigation manually? <a class="header-anchor" href="#can-i-clear-a-mitigation-manually" aria-label="Permalink to &quot;Can I clear a mitigation manually?&quot;">​</a></h3><p>Yes — on the node: <code>DELETE /api/v1/smart/mitigation/{serverId}</code> with the node bearer token. See the <a href="./../user-guide/api#smart-endpoints">API Reference</a>.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><h3 id="what-cron-queue-setup-is-required" tabindex="-1">What cron/queue setup is required? <a class="header-anchor" href="#what-cron-queue-setup-is-required" aria-label="Permalink to &quot;What cron/queue setup is required?&quot;">​</a></h3><p>Two things, both standard Pterodactyl: the scheduler cron (<code>* * * * * php /var/www/pterodactyl/artisan schedule:run</code>) and a queue worker. The scheduler drives <code>firewall-plus:sync-nodes</code> (every minute), <code>reconcile</code> (15 min), <code>cleanup-orphans</code> (30 min), SMART event sync (2 min), and daily audit-log pruning.</p><h3 id="how-do-i-stop-everything-in-an-emergency" tabindex="-1">How do I stop everything in an emergency? <a class="header-anchor" href="#how-do-i-stop-everything-in-an-emergency" aria-label="Permalink to &quot;How do I stop everything in an emergency?&quot;">​</a></h3><p>Admin → <strong>Firewall → Emergency</strong>: enable Emergency mode (blocks all user mutations) and trigger a fleet flush — or from the CLI: <code>php artisan firewall-plus:emergency-flush --all-nodes --confirm</code>. You can also disable specific rule types fleet-wide from the same page.</p><h3 id="is-the-node-daemon-safe-to-expose" tabindex="-1">Is the node daemon safe to expose? <a class="header-anchor" href="#is-the-node-daemon-safe-to-expose" aria-label="Permalink to &quot;Is the node daemon safe to expose?&quot;">​</a></h3><p>It binds to <code>127.0.0.1</code> by default, requires a 64-hex bearer token, enforces an IP whitelist, and rate-limits every route. Keep it on loopback or an internal interface, keep <code>/etc/firewall-plus/token</code> at chmod <code>600</code>, and terminate TLS at a reverse proxy if you need it — the daemon is intentionally HTTP-only. A public bind with an empty IP whitelist refuses to start unless you explicitly opt out.</p>',33)])])}const f=a(i,[["render",r]]);export{p as __pageData,f as default};
